-- PostgreSQL 16 + pgvector. Generated by: python -m app.devtools.dump_schema
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE documents (
	id VARCHAR(32) NOT NULL, 
	filename VARCHAR(512) NOT NULL, 
	stored_path VARCHAR(1024) NOT NULL, 
	file_type VARCHAR(16), 
	mime_type VARCHAR(100), 
	size_bytes BIGINT NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	stage VARCHAR(32) NOT NULL, 
	progress INTEGER NOT NULL, 
	page_count INTEGER NOT NULL, 
	ocr_pages INTEGER NOT NULL, 
	ocr_confidence FLOAT, 
	invoice_count INTEGER NOT NULL, 
	issue_count INTEGER NOT NULL, 
	needs_review BOOLEAN NOT NULL, 
	summary JSONB, 
	extractor VARCHAR(32), 
	error TEXT, 
	attempts INTEGER NOT NULL, 
	processing_ms INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE, 
	finished_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_documents_created_at ON documents (created_at);
CREATE INDEX ix_documents_needs_review ON documents (needs_review);
CREATE INDEX ix_documents_sha256 ON documents (sha256);
CREATE INDEX ix_documents_status ON documents (status);

CREATE TABLE document_pages (
	id SERIAL NOT NULL, 
	document_id VARCHAR(32) NOT NULL, 
	page_no INTEGER NOT NULL, 
	label VARCHAR(255), 
	source VARCHAR(16) NOT NULL, 
	text TEXT NOT NULL, 
	ocr_confidence FLOAT, 
	error TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (document_id, page_no), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE
);
CREATE INDEX ix_document_pages_document_id ON document_pages (document_id);

CREATE TABLE invoices (
	id VARCHAR(32) NOT NULL, 
	document_id VARCHAR(32) NOT NULL, 
	segment_index INTEGER NOT NULL, 
	page_start INTEGER, 
	page_end INTEGER, 
	invoice_number VARCHAR(128), 
	invoice_number_norm VARCHAR(128), 
	invoice_date DATE, 
	supplier_name VARCHAR(255), 
	supplier_norm VARCHAR(255), 
	customer_name VARCHAR(255), 
	subtotal NUMERIC(18, 4), 
	tax NUMERIC(18, 4), 
	total NUMERIC(18, 4), 
	discount NUMERIC(18, 4), 
	shipping NUMERIC(18, 4), 
	currency VARCHAR(8), 
	confidence FLOAT, 
	source VARCHAR(24) NOT NULL, 
	details JSONB, 
	needs_review BOOLEAN NOT NULL, 
	review_status VARCHAR(16) NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE
);
CREATE INDEX ix_invoices_document_id ON invoices (document_id);
CREATE INDEX ix_invoices_dupkey ON invoices (invoice_number_norm, supplier_norm);
CREATE INDEX ix_invoices_invoice_date ON invoices (invoice_date);
CREATE INDEX ix_invoices_needs_review ON invoices (needs_review);
CREATE INDEX ix_invoices_supplier_name ON invoices (supplier_name);

CREATE TABLE processing_events (
	id SERIAL NOT NULL, 
	document_id VARCHAR(32) NOT NULL, 
	stage VARCHAR(32) NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	message TEXT, 
	duration_ms INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE
);
CREATE INDEX ix_processing_events_document_id ON processing_events (document_id);

CREATE TABLE chunks (
	id SERIAL NOT NULL, 
	document_id VARCHAR(32) NOT NULL, 
	invoice_id VARCHAR(32), 
	chunk_index INTEGER NOT NULL, 
	page_no INTEGER, 
	kind VARCHAR(12) NOT NULL, 
	text TEXT NOT NULL, 
	embedding VECTOR(768), 
	embedding_model VARCHAR(64), 
	PRIMARY KEY (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id) ON DELETE CASCADE
);
CREATE INDEX ix_chunks_document_id ON chunks (document_id);
CREATE INDEX ix_chunks_embedding_model ON chunks (embedding_model);

CREATE TABLE corrections (
	id SERIAL NOT NULL, 
	invoice_id VARCHAR(32) NOT NULL, 
	field VARCHAR(64) NOT NULL, 
	old_value TEXT, 
	new_value TEXT, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id) ON DELETE CASCADE
);
CREATE INDEX ix_corrections_invoice_id ON corrections (invoice_id);

CREATE TABLE line_items (
	id SERIAL NOT NULL, 
	invoice_id VARCHAR(32) NOT NULL, 
	position INTEGER NOT NULL, 
	description TEXT, 
	quantity NUMERIC(18, 4), 
	unit_price NUMERIC(18, 4), 
	amount NUMERIC(18, 4), 
	PRIMARY KEY (id), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id) ON DELETE CASCADE
);
CREATE INDEX ix_line_items_invoice_id ON line_items (invoice_id);

CREATE TABLE validation_issues (
	id SERIAL NOT NULL, 
	document_id VARCHAR(32) NOT NULL, 
	invoice_id VARCHAR(32), 
	code VARCHAR(40) NOT NULL, 
	severity VARCHAR(8) NOT NULL, 
	field VARCHAR(64), 
	message TEXT NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id) ON DELETE CASCADE, 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id) ON DELETE CASCADE
);
CREATE INDEX ix_validation_issues_code ON validation_issues (code);
CREATE INDEX ix_validation_issues_document_id ON validation_issues (document_id);
CREATE INDEX ix_validation_issues_invoice_id ON validation_issues (invoice_id);

-- keyword search: full-text index over the extracted text of every page
CREATE INDEX IF NOT EXISTS ix_pages_fts ON document_pages USING GIN (to_tsvector('simple'::regconfig, text));
-- semantic search: approximate nearest-neighbour index (cosine distance)
CREATE INDEX IF NOT EXISTS ix_chunks_embedding ON chunks USING hnsw (embedding vector_cosine_ops);
